const dismissals = new Map<symbol, () => void>()

export function registerBackDismiss(dismiss: () => void) {
  const key = Symbol()
  dismissals.set(key, dismiss)
  return () => {
    dismissals.delete(key)
  }
}

export function dismissTopOverlay() {
  const latest = [...dismissals.entries()].at(-1)
  if (!latest) return false
  dismissals.delete(latest[0])
  latest[1]()
  return true
}

const handlers = new Map<string | symbol, { name: string; priority: number; dismiss: () => boolean }>()
let dispatching = false
export function registerBackHandler(dismiss: () => boolean, priority: number, name?: string) {
  const key = name ?? Symbol()
  const entry = { name: name ?? '', priority, dismiss }
  handlers.set(key, entry)
  return () => {
    if (handlers.get(key) === entry) handlers.delete(key)
  }
}
export function dismissOwnedPage(minimum = 0, maximum = Infinity) {
  if (dispatching) return false
  dispatching = true
  try {
    for (const handler of [...handlers.values()].sort((a, b) => a.priority - b.priority || a.name.localeCompare(b.name))) {
      if (handler.priority >= minimum && handler.priority <= maximum && handler.dismiss()) return true
    }
    return false
  } finally { dispatching = false }
}
