import { onUnmounted, watch } from 'vue'
import type { Ref } from 'vue'
import { registerBackDismiss } from './backDismiss'
export function useOverlayBack(open: Ref<boolean | undefined>, close = () => { open.value = false }) {
  let release: (() => void) | undefined
  watch(open, value => { release?.(); release = value ? registerBackDismiss(close) : undefined }, { flush: 'sync', immediate: true })
  onUnmounted(() => release?.())
}
